-- STATUS: EXECUTED 2026-08-30 against account KUMZGAJ-OO64644 (locator PF13333,
-- AWS_US_EAST_2) via ./tools/sfx as part of tools/deploy_new_account. Ran clean.
-- PARTLY GENERATED by tools/gen_pipeline_sql.py from sql/06b_reconciler.sql,
-- so the procedure body and the standalone script cannot drift apart.
--
-- PIPELINE AUTOMATION — the answer to "who created this data?"
--
-- Until now every stage was a file a human ran by hand. That is a set of
-- scripts, not a product. This makes the pipeline self-running:
--
--   SP_RUN_PIPELINE()     one call performs the whole run and logs it
--   T_HEALTHONE_PIPELINE  a schedule that calls it
--   STREAMS               detect whether clinical data actually changed, so a
--                         scheduled run over unchanged data costs almost nothing
--   PIPELINE_RUN_LOG      every run recorded: when, by what, what changed
--   V_PIPELINE_STATUS     one view answering "is it running, is data fresh?"
--
-- COST DISCIPLINE — why the task ships SUSPENDED.
-- A task is the only thing here that can spend money while nobody watches.
-- So: DAILY schedule (not minutely), the existing XSMALL warehouse rather
-- than serverless compute, and an early exit when no stream has new data. An
-- always-on minutely task would drain this trial in days (docs/02 §5).
--
-- KNOWN GRANT REQUIREMENT: HO_ADMIN can CREATE a task but cannot RESUME or
-- EXECUTE one without an account-level privilege. Tested: EXECUTE TASK
-- returns an error. To enable the schedule, run once as ACCOUNTADMIN:
--   GRANT EXECUTE TASK ON ACCOUNT TO ROLE HO_ADMIN;
-- Until then SP_RUN_PIPELINE() is fully usable by direct call, which is what
-- the app's "Run pipeline now" button does — automation works, only the
-- unattended SCHEDULE is gated.
USE ROLE HO_ADMIN; USE DATABASE HEALTHONE; USE SCHEMA CASES; USE WAREHOUSE HO_WH;

-- ===========================================================================
-- 1. Change detection. A scheduled run should do nothing when nothing moved.
-- ===========================================================================
CREATE STREAM IF NOT EXISTS CONF.STR_LAB_RESULT   ON TABLE CONF.CONF_LAB_RESULT;
CREATE STREAM IF NOT EXISTS CONF.STR_MEDICATION   ON TABLE CONF.CONF_MEDICATION;
CREATE STREAM IF NOT EXISTS CONF.STR_DIAGNOSIS    ON TABLE CONF.CONF_DIAGNOSIS;
CREATE STREAM IF NOT EXISTS RULES.STR_SAFETY_RULE ON TABLE RULES.SAFETY_RULE;

-- ===========================================================================
-- 2. Observability. A pipeline you cannot inspect is not operable.
-- ===========================================================================
CREATE TABLE IF NOT EXISTS PIPELINE_RUN_LOG (
  RUN_ID        VARCHAR(60)  NOT NULL DEFAULT 'RUN-' || UUID_STRING(),
  STARTED_AT    TIMESTAMP_TZ NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  FINISHED_AT   TIMESTAMP_TZ,
  TRIGGERED_BY  VARCHAR(60)  NOT NULL,
  HAD_NEW_DATA  BOOLEAN,
  CASES_BEFORE  NUMBER(9,0),
  CASES_AFTER   NUMBER(9,0),
  EVIDENCE_ROWS NUMBER(9,0),
  OUTCOME       VARCHAR(400),
  PRIMARY KEY (RUN_ID)
);

-- ===========================================================================
-- 3. The reconciler as a callable procedure (body generated from sql/06b).
-- ===========================================================================
CREATE OR REPLACE PROCEDURE SP_RECONCILE_EVIDENCE()
RETURNS STRING
LANGUAGE SQL
COMMENT = 'Rebuild CASE_EVIDENCE for every case. Idempotent: deletes then inserts.'
AS
$$
DECLARE
  n INT DEFAULT 0;
BEGIN
DELETE FROM CASE_EVIDENCE;

-- ============================================================================
-- CLAIM 1 — DRUG_ACTIVE. Is the drug actually active?
-- AGREES when the EHR says ACTIVE and pharmacy has dispensed recently.
-- CONFLICTS when the EHR says ACTIVE but dispensing has stopped — both
-- sources are shown side by side and the system refuses to adjudicate.
-- ============================================================================
INSERT INTO CASE_EVIDENCE (CASE_ID, CLAIM_KEY, CLAIM_TEXT, VERDICT, EVIDENCE_REFS, SEARCHED)
SELECT
  cr.CASE_ID,
  'DRUG_ACTIVE',
  d.DRUG_NAME || ' is recorded as an active medication for this patient.',
  IFF(am.FILLS_LAST_90D > 0, 'AGREES', 'CONFLICTS'),
  ARRAY_CAT(
    ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(
      'type', 'medication', 'source_system', 'EHR',
      'source_record_id', am.MED_SOURCE_RECORD_IDS[0]::STRING,
      'detail', d.DRUG_NAME || ', status ACTIVE, therapy start '
                || TO_VARCHAR(am.THERAPY_START_DATE, 'YYYY-MM-DD'))),
    IFF(am.LAST_FILL_DATE IS NULL,
      ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(
        'type', 'pharmacy_fill', 'source_system', 'PHARMACY',
        'source_record_id', 'none',
        'detail', 'No pharmacy fill on record for this medication')),
      ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(
        'type', 'pharmacy_fill', 'source_system', 'PHARMACY',
        'source_record_id', COALESCE(lf.SOURCE_RECORD_ID, 'unknown'),
        'detail', 'Last fill dispensed ' || TO_VARCHAR(am.LAST_FILL_DATE, 'YYYY-MM-DD')
                  || ' (' || am.FILLS_LAST_90D::STRING || ' fill(s) in the last 90 days)')))
  ),
  NULL
FROM CASE_REGISTRY cr
JOIN P360.P360_ACTIVE_MEDICATION am
      ON am.PERSON_ID = cr.PERSON_ID AND am.DRUG_ID = cr.DRUG_ID
JOIN CONF.REF_DRUG d ON d.DRUG_ID = cr.DRUG_ID
LEFT JOIN CONF.CONF_PHARMACY_FILL lf
      ON lf.PERSON_ID = am.PERSON_ID AND lf.DRUG_ID = am.DRUG_ID
     AND lf.FILL_DATE = am.LAST_FILL_DATE;

-- ============================================================================
-- CLAIM 2 — MEDICATION_DISPENSING. MED_CONFLICT cases only. The note that
-- explains WHY dispensing stopped is human context a reviewer needs, and it
-- is citable. Three sources end up side by side (EHR / PHARMACY / NOTE) with
-- no adjudication language anywhere.
-- ============================================================================
INSERT INTO CASE_EVIDENCE (CASE_ID, CLAIM_KEY, CLAIM_TEXT, VERDICT, EVIDENCE_REFS, SEARCHED)
SELECT
  cr.CASE_ID,
  'MEDICATION_DISPENSING',
  'The clinical record contains a note relevant to whether this medication is still being taken.',
  'CONFLICTS',
  ARRAY_AGG(OBJECT_CONSTRUCT(
    'type', 'clinical_note', 'source_system', 'EHR',
    'source_record_id', n.SOURCE_RECORD_ID,
    'detail', TO_VARCHAR(n.NOTE_DATE, 'YYYY-MM-DD') || ' (' || COALESCE(n.AUTHOR_ROLE, 'unknown')
              || '): ' || n.NOTE_TEXT)) WITHIN GROUP (ORDER BY n.NOTE_DATE DESC),
  NULL
FROM CASE_REGISTRY cr
JOIN CONF.CONF_CLINICAL_NOTE n ON n.PERSON_ID = cr.PERSON_ID
WHERE cr.CASE_TYPE = 'MED_CONFLICT'
  AND (LOWER(n.NOTE_TEXT) LIKE '%stop%'
       OR LOWER(n.NOTE_TEXT) LIKE '%discontinu%'
       OR LOWER(n.NOTE_TEXT) LIKE '%not collect%')
GROUP BY cr.CASE_ID;

-- ============================================================================
-- CLAIM 3 — CONDITION_PRESENT. Rule-driven cases only. AGREES when the
-- provider-side diagnosis is corroborated by payer-side claims: two
-- independent systems, which is the entire point of a payvider 360.
-- ============================================================================
INSERT INTO CASE_EVIDENCE (CASE_ID, CLAIM_KEY, CLAIM_TEXT, VERDICT, EVIDENCE_REFS, SEARCHED)
WITH dx AS (
  SELECT cr.CASE_ID, cr.PERSON_ID, r.CONDITION_ID,
         MIN(dg.ONSET_DATE)       AS ONSET_DATE,
         MIN(dg.SOURCE_RECORD_ID) AS DX_REF
  FROM CASE_REGISTRY cr
  JOIN RULES.SAFETY_RULE r ON r.RULE_ID = cr.RULE_ID AND r.VERSION = cr.VERSION
  JOIN CONF.CONF_DIAGNOSIS dg
        ON dg.PERSON_ID = cr.PERSON_ID AND dg.CONDITION_ID = r.CONDITION_ID
  WHERE cr.CASE_TYPE = 'MONITORING_GAP'
  GROUP BY cr.CASE_ID, cr.PERSON_ID, r.CONDITION_ID
),
cl AS (
  SELECT dx.CASE_ID,
         MAX(c.SERVICE_DATE)     AS SERVICE_DATE,
         MAX(c.SOURCE_RECORD_ID) AS CLAIM_REF,
         MAX(c.SERVICE_DESC)     AS SERVICE_DESC,
         COUNT(*)                AS N
  FROM dx
  JOIN CONF.CONF_CLAIM_LINE c
        ON c.PERSON_ID = dx.PERSON_ID AND c.CONDITION_ID = dx.CONDITION_ID
  GROUP BY dx.CASE_ID
)
SELECT
  dx.CASE_ID, 'CONDITION_PRESENT',
  'A diagnosis of ' || cond.CONDITION_NAME || ' is recorded for this patient.',
  'AGREES',
  ARRAY_CAT(
    ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(
      'type', 'diagnosis', 'source_system', 'EHR', 'source_record_id', dx.DX_REF,
      'detail', INITCAP(cond.CONDITION_NAME) || ', onset '
                || TO_VARCHAR(dx.ONSET_DATE, 'YYYY-MM-DD'))),
    IFF(cl.CASE_ID IS NULL, ARRAY_CONSTRUCT(),
      ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(
        'type', 'claim_line', 'source_system', 'CLAIMS', 'source_record_id', cl.CLAIM_REF,
        'detail', cl.SERVICE_DESC || ', ' || TO_VARCHAR(cl.SERVICE_DATE, 'YYYY-MM-DD')
                  || ' (' || cl.N::STRING || ' condition-linked claim line(s))')))
  ),
  NULL
FROM dx
JOIN CONF.REF_CONDITION cond ON cond.CONDITION_ID = dx.CONDITION_ID
LEFT JOIN cl ON cl.CASE_ID = dx.CASE_ID;

-- ============================================================================
-- CLAIM 4 — REQUIRED_LAB. The heart of it. MISSING carries the verbatim
-- negative-evidence sentence, plus a SEARCHED string stating the exact scope
-- INCLUDING that unmappable test names were excluded — which is what lets a
-- reviewer understand GP3 and dismiss it correctly.
-- ============================================================================
INSERT INTO CASE_EVIDENCE (CASE_ID, CLAIM_KEY, CLAIM_TEXT, VERDICT, EVIDENCE_REFS, SEARCHED)
SELECT
  cr.CASE_ID, 'REQUIRED_LAB',
  'No ' || t.CANONICAL_NAME || ' result was found in the available records between '
    || TO_VARCHAR(cr.WINDOW_START_DATE, 'YYYY-MM-DD') || ' and '
    || TO_VARCHAR(a.AS_OF, 'YYYY-MM-DD') || '.',
  'MISSING',
  ARRAY_CONSTRUCT(),
  'CONF_LAB_RESULT via P360_LAB_TIMELINE; test = ' || t.CANONICAL_NAME
    || ' (' || t.LAB_TEST_ID || '); person ' || cr.PERSON_ID
    || '; window ' || TO_VARCHAR(cr.WINDOW_START_DATE, 'YYYY-MM-DD')
    || ' to ' || TO_VARCHAR(a.AS_OF, 'YYYY-MM-DD')
    || ' (later of therapy start, condition onset, and interval plus grace). '
    || 'Results whose recorded test name could not be mapped to the controlled '
    || 'vocabulary are EXCLUDED from this search and are shown separately in the '
    || 'lab timeline.'
FROM CASE_REGISTRY cr
CROSS JOIN CONF.DATE_ANCHOR a
JOIN CONF.REF_LAB_TEST t ON t.LAB_TEST_ID = cr.LAB_TEST_ID
WHERE cr.CASE_TYPE = 'MONITORING_GAP';

-- ============================================================================
-- CLAIM 5 — UNMAPPED_LAB. The honesty claim, and the reason GP3 is
-- DISMISSIBLE rather than simply wrong. If the person has results in the
-- window under a test name we could not map, say so plainly and cite them.
-- Verdict CONFLICTS: our vocabulary and the lab feed disagree about what
-- exists. This single row turns "the system is wrong" into "the system told
-- me exactly why it could not tell" — and it is what the reviewer dismisses on.
-- ============================================================================
INSERT INTO CASE_EVIDENCE (CASE_ID, CLAIM_KEY, CLAIM_TEXT, VERDICT, EVIDENCE_REFS, SEARCHED)
SELECT
  cr.CASE_ID, 'UNMAPPED_LAB',
  'Laboratory results exist for this patient inside the monitoring window under a test '
    || 'name that is not mapped to the controlled vocabulary, so they could not be '
    || 'evaluated against the rule.',
  'CONFLICTS',
  ARRAY_AGG(OBJECT_CONSTRUCT(
    'type', 'lab_result_unmapped', 'source_system', 'LAB',
    'source_record_id', l.SOURCE_RECORD_ID,
    'detail', TO_VARCHAR(l.RESULT_DATE, 'YYYY-MM-DD') || ': "' || l.RAW_TEST_TEXT
              || '" = ' || COALESCE(l.RESULT_VALUE::STRING, 'no value')
              || ' ' || COALESCE(l.UNITS, '')))
    WITHIN GROUP (ORDER BY l.RESULT_DATE DESC),
  'CONF_LAB_RESULT where LAB_TEST_ID IS NULL for person ' || cr.PERSON_ID
    || ', window ' || TO_VARCHAR(cr.WINDOW_START_DATE, 'YYYY-MM-DD')
    || ' onward. Shown because a reviewer must be able to see what the system could not.'
FROM CASE_REGISTRY cr
CROSS JOIN CONF.DATE_ANCHOR a
JOIN CONF.CONF_LAB_RESULT l ON l.PERSON_ID = cr.PERSON_ID
WHERE cr.CASE_TYPE = 'MONITORING_GAP'
  AND l.LAB_TEST_ID IS NULL
  AND l.RESULT_DATE >= cr.WINDOW_START_DATE
  AND l.RESULT_DATE <= a.AS_OF
GROUP BY cr.CASE_ID, cr.PERSON_ID, cr.WINDOW_START_DATE;

-- ============================================================================
-- Audit + summary
-- ============================================================================
INSERT INTO AUDIT_EVENT (EVENT_TYPE, ACTOR, SUBJECT_TYPE, SUBJECT_ID, DETAIL)
SELECT 'CASE_REFRESHED', 'system:reconciler', 'QUEUE', 'ALL',
       OBJECT_CONSTRUCT('evidence_rows', COUNT(*), 'cases', COUNT(DISTINCT CASE_ID))
FROM CASE_EVIDENCE;

  SELECT COUNT(*) INTO :n FROM CASE_EVIDENCE;
  RETURN 'evidence rows: ' || :n;
END;
$$;

-- ===========================================================================
-- 4. The whole run, as one idempotent call.
-- ===========================================================================
CREATE OR REPLACE PROCEDURE SP_RUN_PIPELINE(P_TRIGGERED_BY STRING, P_FORCE BOOLEAN)
RETURNS VARIANT
LANGUAGE SQL
COMMENT = 'Full pipeline: refresh 360, detect, merge, reconcile, seal audit.'
AS
$$
DECLARE
  run_id   STRING;
  new_data BOOLEAN DEFAULT FALSE;
  before_n INT DEFAULT 0;
  after_n  INT DEFAULT 0;
  ev_n     INT DEFAULT 0;
BEGIN
  SELECT 'RUN-' || UUID_STRING() INTO :run_id;
  SELECT COUNT(*) INTO :before_n FROM CASE_REGISTRY WHERE STATUS = 'OPEN';

  -- Did anything actually change? A scheduled run over unchanged data should
  -- cost a metadata check, not a full refresh.
  SELECT (SYSTEM$STREAM_HAS_DATA('CONF.STR_LAB_RESULT')
       OR SYSTEM$STREAM_HAS_DATA('CONF.STR_MEDICATION')
       OR SYSTEM$STREAM_HAS_DATA('CONF.STR_DIAGNOSIS')
       OR SYSTEM$STREAM_HAS_DATA('RULES.STR_SAFETY_RULE')) INTO :new_data;

  INSERT INTO PIPELINE_RUN_LOG (RUN_ID, TRIGGERED_BY, HAD_NEW_DATA, CASES_BEFORE)
  SELECT :run_id, :P_TRIGGERED_BY, :new_data, :before_n;

  IF (NOT :new_data AND NOT :P_FORCE) THEN
    UPDATE PIPELINE_RUN_LOG
       SET FINISHED_AT = CURRENT_TIMESTAMP(), CASES_AFTER = :before_n,
           OUTCOME = 'skipped - no new clinical data or rule change'
     WHERE RUN_ID = :run_id;
    RETURN OBJECT_CONSTRUCT('ok', TRUE, 'run_id', :run_id, 'skipped', TRUE,
                            'reason', 'no new data', 'open_cases', :before_n);
  END IF;

  -- Ordered refresh: SCHEDULER=DISABLE means a manual refresh does NOT
  -- cascade upstream, so sources must be current before their consumers.
  ALTER DYNAMIC TABLE P360.P360_MEDICATION_TIMELINE REFRESH;
  ALTER DYNAMIC TABLE P360.P360_LAB_TIMELINE        REFRESH;
  ALTER DYNAMIC TABLE P360.P360_ACTIVE_MEDICATION   REFRESH;
  ALTER DYNAMIC TABLE P360.P360_PERSON              REFRESH;
  ALTER DYNAMIC TABLE CASES.DT_CASE_CANDIDATE       REFRESH;

  MERGE INTO CASE_REGISTRY t
  USING DT_CASE_CANDIDATE s ON t.CANDIDATE_KEY = s.CANDIDATE_KEY
  WHEN MATCHED THEN UPDATE SET
     t.VERSION = s.VERSION, t.PRIORITY = s.PRIORITY,
     t.PRIORITY_FACTORS = s.PRIORITY_FACTORS,
     t.WINDOW_START_DATE = s.WINDOW_START_DATE,
     t.REFERENCE_EVENT_TYPE = s.REFERENCE_EVENT_TYPE,
     t.REFERENCE_EVENT_DATE = s.REFERENCE_EVENT_DATE,
     t.DAYS_SINCE_REFERENCE = s.DAYS_SINCE_REFERENCE,
     t.LAST_REFRESHED_AT = CURRENT_TIMESTAMP()
  WHEN NOT MATCHED THEN INSERT
     (CANDIDATE_KEY, PERSON_ID, CASE_TYPE, RULE_ID, VERSION, DRUG_ID, LAB_TEST_ID,
      PRIORITY, PRIORITY_FACTORS, WINDOW_START_DATE, REFERENCE_EVENT_TYPE,
      REFERENCE_EVENT_DATE, DAYS_SINCE_REFERENCE, STATUS, LAST_REFRESHED_AT)
     VALUES
     (s.CANDIDATE_KEY, s.PERSON_ID, s.CASE_TYPE, s.RULE_ID, s.VERSION, s.DRUG_ID,
      s.LAB_TEST_ID, s.PRIORITY, s.PRIORITY_FACTORS, s.WINDOW_START_DATE,
      s.REFERENCE_EVENT_TYPE, s.REFERENCE_EVENT_DATE, s.DAYS_SINCE_REFERENCE,
      'OPEN', CURRENT_TIMESTAMP());

  -- A patient who finally got tested leaves the queue by itself, and says why.
  UPDATE CASE_REGISTRY t
     SET STATUS = 'RESOLVED_BY_DATA', LAST_REFRESHED_AT = CURRENT_TIMESTAMP()
   WHERE t.STATUS = 'OPEN'
     AND NOT EXISTS (SELECT 1 FROM DT_CASE_CANDIDATE s
                      WHERE s.CANDIDATE_KEY = t.CANDIDATE_KEY);

  CALL SP_RECONCILE_EVIDENCE();
  CALL SEAL_AUDIT_CHAIN();

  SELECT COUNT(*) INTO :after_n FROM CASE_REGISTRY WHERE STATUS = 'OPEN';
  SELECT COUNT(*) INTO :ev_n    FROM CASE_EVIDENCE;

  UPDATE PIPELINE_RUN_LOG
     SET FINISHED_AT = CURRENT_TIMESTAMP(), CASES_AFTER = :after_n,
         EVIDENCE_ROWS = :ev_n,
         OUTCOME = 'completed - net case change ' || (:after_n - :before_n)::STRING
   WHERE RUN_ID = :run_id;

  INSERT INTO AUDIT_EVENT (EVENT_TYPE, ACTOR, SUBJECT_TYPE, SUBJECT_ID, DETAIL)
  SELECT 'QUEUE_REFRESHED', CURRENT_USER(), 'QUEUE', 'ALL',
         OBJECT_CONSTRUCT('run_id', :run_id, 'triggered_by', :P_TRIGGERED_BY,
                          'open_before', :before_n, 'open_after', :after_n,
                          'evidence_rows', :ev_n);

  RETURN OBJECT_CONSTRUCT('ok', TRUE, 'run_id', :run_id, 'skipped', FALSE,
                          'open_before', :before_n, 'open_after', :after_n,
                          'evidence_rows', :ev_n);
END;
$$;

-- ===========================================================================
-- 5. The schedule. Ships SUSPENDED on purpose - see the cost note above.
--    Toggle from the app's Operations page, or:
--      ALTER TASK T_HEALTHONE_PIPELINE RESUME;   -- scheduling ON
--      ALTER TASK T_HEALTHONE_PIPELINE SUSPEND;  -- scheduling OFF
-- ===========================================================================
CREATE OR REPLACE TASK T_HEALTHONE_PIPELINE
  WAREHOUSE = HO_WH
  SCHEDULE = 'USING CRON 0 6 * * * UTC'
  COMMENT = 'Nightly re-evaluation of all ACTIVE rules against the 360.'
AS
  CALL SP_RUN_PIPELINE('TASK', FALSE);

-- ===========================================================================
-- 6. Operational status in one view.
-- ===========================================================================
CREATE OR REPLACE VIEW V_PIPELINE_STATUS
COMMENT = 'Is the pipeline running, when did it last run, and is data fresh?'
AS
SELECT
  (SELECT COUNT(*) FROM CASE_REGISTRY WHERE STATUS='OPEN')           AS OPEN_CASES,
  (SELECT COUNT(*) FROM CASE_EVIDENCE)                               AS EVIDENCE_ROWS,
  (SELECT COUNT(*) FROM RULES.SAFETY_RULE WHERE STATUS='ACTIVE')     AS ACTIVE_RULES,
  (SELECT MAX(FINISHED_AT) FROM PIPELINE_RUN_LOG)                    AS LAST_RUN_AT,
  (SELECT OUTCOME FROM PIPELINE_RUN_LOG
    WHERE FINISHED_AT IS NOT NULL ORDER BY FINISHED_AT DESC LIMIT 1) AS LAST_OUTCOME,
  (SELECT TRIGGERED_BY FROM PIPELINE_RUN_LOG
    WHERE FINISHED_AT IS NOT NULL ORDER BY FINISHED_AT DESC LIMIT 1) AS LAST_TRIGGER,
  (SELECT COUNT(*) FROM PIPELINE_RUN_LOG)                            AS TOTAL_RUNS,
  (SELECT AS_OF FROM CONF.DATE_ANCHOR)                               AS EVALUATION_DATE;

GRANT SELECT ON VIEW V_PIPELINE_STATUS TO ROLE HO_REVIEWER;
GRANT SELECT ON TABLE PIPELINE_RUN_LOG TO ROLE HO_REVIEWER;
GRANT SELECT ON VIEW V_PIPELINE_STATUS TO ROLE HO_AUDITOR;
GRANT SELECT ON TABLE PIPELINE_RUN_LOG TO ROLE HO_AUDITOR;
GRANT USAGE ON PROCEDURE SP_RUN_PIPELINE(STRING, BOOLEAN) TO ROLE HO_REVIEWER;

SELECT 'pipeline automation deployed' AS STATUS;
